fn rle(s) {
  out = []
  i = 0
  while i < len(s) {
    j = i
    while j < len(s) && s[j] == s[i] {
      j += 1
    }
    out.append(s[i] + str(j - i))
    i = j
  }
  ret "".join(out)
}

