fn roman(s) {
  v = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
  total = 0
  for i in range(len(s)) {
    if i + 1 < len(s) && v[s[i]] < v[s[i + 1]] {
      total -= v[s[i]]
    } el {
      total += v[s[i]]
    }
  }
  ret total
}

fn two_sum(nums, target) {
  seen = {}
  for i, x in enumerate(nums) {
    if target - x in seen {
      ret [seen[target - x], i]
    }
    seen[x] = i
  }
}

